@php($attentionTasks=$tasks->filter(fn($task)=>in_array($task->status,['Awaiting marking','Referred'],true)||($task->template['kind']??'source-pending')==='source-pending')->sortBy(fn($task)=>[$task->due_date?->format('Y-m-d')??'9999-12-31',$task->id])->values())
<section class="panel"><h2>Tasks needing attention</h2><p>{{ $attentionTasks->count() }} allocated tasks need a decision, response or source check in this scope. Ordered by recorded due date; undated tasks follow.</p>
@if($attentionTasks->isEmpty())<div class="visual-empty"><strong>No matching tasks in this view</strong>Check allocations and filters if you expected to see work here. This does not confirm that every apprenticeship requirement is complete.</div>@else
<div class="table-scroll"><table class="visual-task-list"><thead><tr><th scope="col">Apprentice</th><th scope="col">Task</th><th scope="col">Status</th><th scope="col">Due</th><th scope="col">Next action</th></tr></thead><tbody>@foreach($attentionTasks->take(12) as $task)<tr><th scope="row">{{ $task->apprentice->first_name }} {{ $task->apprentice->last_name }}</th><td>{{ $task->title }}<br><small>Block {{ $task->block }} · {{ $task->reference }}</small></td><td>{{ ($task->template['kind']??'source-pending')==='source-pending'?'Source needs checking':$task->status }}</td><td>{{ $task->due_date?->format('d M Y')??'Date needs checking' }}</td><td><a class="button" href="{{ route('tasks.show',$task) }}">Open task</a></td></tr>@endforeach</tbody></table></div><p class="muted">Showing {{ min(12,$attentionTasks->count()) }} of {{ $attentionTasks->count() }}. Use the apprentice’s Tasks page for their full task list.</p>@endif</section>
